var HOOKS = { claude: claudeHook, antigravity: antigravityHook };
async function goalDispatch(sub, argv) {
  if (!sub) {
    console.log(GOAL_HELP[""]);
    return 2;
  }
  const p = parseArgs(argv, ["all", "json", "force", "check"]);
  if (p.flags.has("help")) {
    console.log(GOAL_HELP[sub] ?? GOAL_HELP[""]);
    return 0;
  }
  const out = (s) => console.log(s);
  switch (sub) {
    case "create": {
      unknownFlags(p, ["prompt", "session", "max-turns", "force"]);
      const objective = (str(p, "prompt") ?? (process.stdin.isTTY ? "" : await Bun.stdin.text())).trim();
      if (!objective)
        throw new UsageError("give the objective with --prompt or on stdin");
      const me = whoami();
      const addr = str(p, "session") ?? me;
      if (!addr)
        throw new Error("cannot tell which session this is; pass --session <provider>:<id>");
      const { provider, id: sessionId } = splitAddress(addr);
      const adapter = adapterFor(provider);
      const store = new Store;
      const existing = store.activeGoal(provider, sessionId);
      if (existing)
        throw new Error(`${addr} already has the active goal ${existing.id}; finish it (goal done|blocked) or delete it first`);
      const live = adapter.liveness(store, sessionId);
      if (live.state === "dead" && !bool(p, "force"))
        throw new Error(`${addr} does not look open (${live.detail}). Use --force to create the goal anyway`);
      const rawTurns = str(p, "max-turns");
      const maxTurns = rawTurns === undefined ? UNLIMITED_TURNS : Number(rawTurns);
      if (rawTurns !== undefined && !(Number.isInteger(maxTurns) && maxTurns >= 1))
        throw new UsageError("--max-turns must be a whole number, 1 or more");
      const now = Date.now();
      const g = { id: store.newGoalId(), provider, session_id: sessionId, cwd: process.cwd(), objective, status: "active", turns: 0, max_turns: maxTurns, compactions: -1, created_at: now, updated_at: now, note: "" };
      store.insertGoal(g);
      if (addr === me) {
        out(`GOAL ${g.id} set for this session. Work toward it now; it is sent again at every turn end until you run \`${selfCommand()} goal done ${g.id}\` or \`... goal blocked ${g.id}\`.`);
      } else {
        const d = live.state === "live" ? adapter.deliver(store, sessionId, g.id, startText(g)) : { ok: false, detail: `session state is ${live.state}: ${live.detail}` };
        out(`GOAL ${g.id} set for ${addr}; start ${d.ok ? "sent: " + d.detail : "not sent: " + d.detail}`);
      }
      if (adapter.poll) {
        const d = ensureDaemon(store);
        out(`DAEMON: ${d.started ? "started" : "running"} (pid ${d.pid}); ${provider} has no hook, so the daemon watches the session for turn ends`);
      }
      if (provider === "claude") {
        try {
          const list = JSON.parse(run("claude", ["agents", "--json"]).out);
          projectDir = list.find((x) => x.sessionId === sessionId)?.cwd ?? projectDir;
        } catch {}
      }
      const hint = setupHint(provider);
      if (hint)
        out(hint);
      return 0;
    }
    case "list": {
      unknownFlags(p, ["all", "session", "json"]);
      const rows = new Store().goals({ all: bool(p, "all"), address: str(p, "session") });
      if (bool(p, "json"))
        out(JSON.stringify(rows, null, 2));
      else if (rows.length === 0)
        out("No goals.");
      else
        for (const g of rows)
          out(goalLine(g));
      return 0;
    }
    case "show": {
      unknownFlags(p, ["json"]);
      const id = p.positionals[0];
      if (!id)
        throw new UsageError("show needs a goal id");
      const g = needGoal(new Store().goal(id), id);
      if (bool(p, "json"))
        out(JSON.stringify(g, null, 2));
      else {
        out(goalLine(g));
        out(`objective: ${g.objective}`);
        if (g.note)
          out(`note: ${g.note}`);
      }
      return 0;
    }
    case "done":
    case "blocked":
    case "pause":
    case "resume": {
      unknownFlags(p, ["note"]);
      const id = p.positionals[0];
      if (!id)
        throw new UsageError(`${sub} needs a goal id`);
      const store = new Store;
      const g = needGoal(store.goal(id), id);
      const status = { done: "done", blocked: "blocked", pause: "paused", resume: "active" }[sub];
      if (sub === "resume" && g.status !== "paused")
        throw new Error(`${id} is ${g.status}, not paused`);
      if (sub !== "resume" && g.status !== "active" && g.status !== "paused")
        throw new Error(`${id} is already ${g.status}`);
      store.updateGoal(id, { status, note: str(p, "note") ?? g.note });
      out(`${status.toUpperCase()} ${id}`);
      return 0;
    }
    case "delete": {
      unknownFlags(p, []);
      if (p.positionals.length === 0)
        throw new UsageError("delete needs one or more goal ids");
      const store = new Store;
      let missing = 0;
      for (const id of p.positionals) {
        if (store.deleteGoal(id))
          out(`DELETED ${id}`);
        else {
          out(`no goal ${id}`);
          missing++;
        }
      }
      return missing ? 1 : 0;
    }
    case "setup": {
      unknownFlags(p, ["check"]);
      const provider = p.positionals[0];
      if (!provider)
        throw new UsageError("setup needs a provider: claude, opencode, antigravity or pi");
      adapterFor(provider);
      const s = SETUP[provider];
      if (!s)
        throw new Error(`no goal setup is built for ${provider} yet`);
      if (bool(p, "check")) {
        const where = s.check();
        out(where ? `OK ${provider}: configured in ${where}` : `MISSING ${provider}: run \`agent-job goal setup ${provider}\``);
        return where ? 0 : 1;
      }
      out(s.text(selfCommand()));
      return 0;
    }
    case "event": {
      unknownFlags(p, ["session", "raw"]);
      const ev = p.positionals[0];
      const known = ev === "turn-end" || ev === "compacted" || ev === "resumed";
      if (!known && ev !== "aborted")
        throw new UsageError("event takes turn-end, compacted, resumed or aborted");
      const addr = str(p, "session") ?? whoami();
      if (!addr)
        throw new Error("cannot tell which session this is; pass --session");
      trace("event-cmd", ev, { addr, raw: str(p, "raw") });
      if (!known) {
        trace("goal", "turn-end", { addr, decision: "none", why: "aborted by the user" });
        return 0;
      }
      const text = onGoalEvent(new Store, addr, ev);
      if (text)
        process.stdout.write(text + `
`);
      return 0;
    }
    case "hook": {
      const provider = p.positionals[0];
      try {
        const reply = HOOKS[provider ?? ""]?.(await Bun.stdin.text(), p.positionals[1]) ?? "";
        if (reply)
          process.stdout.write(reply + `
`);
      } catch {}
      return 0;
    }
    default:
      throw new UsageError(`unknown goal command "${sub}"`);
  }
}

// src/main.ts
var CRON = ["create", "list", "show", "pause", "resume", "run-now", "delete"];
var [cmd, ...rest] = process.argv.slice(2);
if (!cmd || cmd === "--help" || cmd === "-h" || cmd === "help") {
  console.log(HELP[""]);
  process.exit(cmd ? 0 : 2);
}
var label = cmd;
try {
  if (cmd === "goal") {
    label = `goal ${rest[0] ?? ""}`.trim();
    process.exitCode = await goalDispatch(rest[0], rest.slice(1));
  } else if (cmd === "cron") {
    const sub = rest[0];
    if (!sub || sub === "--help") {
      console.log(HELP["cron"]);
      process.exit(sub ? 0 : 2);
    }
    if (!CRON.includes(sub))
      throw new UsageError(`unknown cron command "${sub}"`);
    label = `cron ${sub}`;
    process.exitCode = await dispatch(sub, rest.slice(1));
  } else {
    process.exitCode = await dispatch(cmd, rest);
  }
} catch (e) {
  const msg = e instanceof Error ? e.message : String(e);
  if (e instanceof UsageError) {
    console.error(`agent-job ${label}: ${msg}
Run \`agent-job ${label} --help\` for usage.`);
    process.exitCode = 2;
  } else {
    console.error(`agent-job ${label}: ${msg}`);
    process.exitCode = 1;
  }
}
